def test_multiline_indentation(filter_cls, varname):
    statement = sql.Statement([
        sql.Token(T.Text, 'select *'),
        sql.Token(T.Whitespace, '\n  '),
        sql.Token(T.Text, 'from foo;'),
    ])
    output_tokens = list(filter_cls(varname).process(statement).tokens)
